let element = null;
let dotNetRef = null;
let timeoutMs = 300000;
let timerId = null;
let isIdle = false;

const activityEvents = ["mousemove", "keydown", "click", "scroll", "touchstart"];

function onActivity() {
    if (isIdle) {
        isIdle = false;
        dotNetRef.invokeMethodAsync("OnUserActive");
    }
    resetTimer();
}

function resetTimer() {
    if (timerId !== null) {
        clearTimeout(timerId);
    }
    timerId = setTimeout(() => {
        isIdle = true;
        dotNetRef.invokeMethodAsync("OnUserIdle");
    }, timeoutMs);
}

